class Solution:
    def maxNumberOfAlloys(self, n: int, k: int, budget: int,
                          composition: List[List[int]], stock: List[int], cost: List[int]) -> int:
        def ok(comp, t):
            need = 0
            for j in range(n):
                short = comp[j] * t - stock[j]
                if short > 0:
                    need += short * cost[j]
                    if need > budget:
                        return False
            return need <= budget
        ans = 0
        for comp in composition:
            lo, hi = 0, 2 * 10**8
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if ok(comp, mid):
                    lo = mid
                else:
                    hi = mid - 1
            ans = max(ans, lo)
        return ans

