class Solution {
public:
    int maxNumberOfAlloys(int n, int k, int budget, vector<vector<int>>& composition,
                          vector<int>& stock, vector<int>& cost) {
        auto ok = [&](vector<int>& comp, long long t) {
            long long need = 0;
            for (int j = 0; j < n; ++j) {
                long long sh = (long long)comp[j] * t - stock[j];
                if (sh > 0) { need += sh * cost[j]; if (need > budget) return false; }
            }
            return need <= budget;
        };
        int ans = 0;
        for (auto& comp : composition) {
            long long lo = 0, hi = 2e8;
            while (lo < hi) {
                long long mid = (lo + hi + 1) / 2;
                if (ok(comp, mid)) lo = mid; else hi = mid - 1;
            }
            ans = max(ans, (int)lo);
        }
        return ans;
    }
};

