class Solution {
    public int maxNumberOfAlloys(int n, int k, int budget, List<List<Integer>> composition,
                                 List<Integer> stock, List<Integer> cost) {
        int ans = 0;
        for (List<Integer> comp : composition) {
            long lo = 0, hi = 200000000L;
            while (lo < hi) {
                long mid = (lo + hi + 1) / 2, need = 0;
                boolean ok = true;
                for (int j = 0; j < n && ok; j++) {
                    long sh = (long) comp.get(j) * mid - stock.get(j);
                    if (sh > 0) need += sh * cost.get(j);
                    if (need > budget) ok = false;
                }
                if (ok) lo = mid; else hi = mid - 1;
            }
            ans = Math.max(ans, (int) lo);
        }
        return ans;
    }
}

