var maxNumberOfAlloys = function(n, k, budget, composition, stock, cost) {
    const ok = (comp, t) => {
        let need = 0;
        for (let j = 0; j < n; j++) {
            const sh = comp[j] * t - stock[j];
            if (sh > 0) { need += sh * cost[j]; if (need > budget) return false; }
        }
        return need <= budget;
    };
    let ans = 0;
    for (const comp of composition) {
        let lo = 0, hi = 2e8;
        while (lo < hi) {
            const mid = Math.floor((lo + hi + 1) / 2);
            if (ok(comp, mid)) lo = mid; else hi = mid - 1;
        }
        ans = Math.max(ans, lo);
    }
    return ans;
};
